#include "../../models/film_three_finger/SharedFilmSystem.h"
#include <fstream>
#include <iomanip>
#include <iostream>
using namespace regrip_three_finger;
int main(int argc,char**argv){try{
 if(argc!=3)throw std::runtime_error("actual V1 checkpoint,output required");std::ifstream in(argv[1]);std::string magic,identity;double time,dt;unsigned index;in>>magic>>time>>dt>>index>>identity;if(magic!="REGRIP_PERSISTENT_V1")throw std::runtime_error("bounded V1 Hold reference only");
 SharedFilmSystem s(Layout(),{0,0,-.001});unsigned n=s.initial.size(),nf=s.shared.nf;Eigen::VectorXd q(n),v(n);for(double&x:q)in>>x;for(double&x:v)in>>x;Eigen::Vector4d quat;for(double&x:quat)in>>x;if(!q.allFinite()||!v.allFinite()||std::abs(quat.squaredNorm()-1)>1e-14)throw std::runtime_error("invalid actual state");s.shared.M.setZero();
 for(unsigned f=0;f<3;++f){auto&m=s.shared.films[f].film;for(unsigned i=0;i<m.mass.size();++i){in>>m.mass[i];for(unsigned d=0;d<3;++d){unsigned a=3*i+d;if(m.index[a]>=0)s.shared.M(f*nf+m.index[a],f*nf+m.index[a])+=m.mass[i]*m.weight[a]*m.weight[a];}}}
 for(unsigned i=0;i<6;++i)for(unsigned j=0;j<6;++j)in>>s.shared.M(3*nf+i,3*nf+j);for(unsigned f=0;f<3;++f){const auto&m=s.shared.films[f].film;for(unsigned a=0;a<m.index.size();++a){int id;double w;in>>id>>w;if(id!=m.index[a]||w!=m.weight[a])throw std::runtime_error("actual root map differs");}s.owned[f]=124;s.features[f]=6;}
 if(!in)throw std::runtime_error("actual mass/root state incomplete");auto g=s.geometry(q);Eigen::VectorXd diag=s.shared.M.diagonal();if(diag.minCoeff()<=0||(s.shared.M-diag.asDiagonal().toDenseMatrix()).cwiseAbs().maxCoeff()!=0||g.gap.cwiseAbs().maxCoeff()>1e-10||(g.J*v).cwiseAbs().maxCoeff()>1e-10)throw std::runtime_error("touching tangent state/diagonal public mass required");
 Eigen::MatrixXd miJ=g.J.transpose();for(unsigned i=0;i<n;++i)miJ.row(i)/=diag(i);Eigen::MatrixXd W=g.J*miJ;Eigen::LDLT<Eigen::MatrixXd>factor(W);if(factor.info()!=Eigen::Success||factor.vectorD().minCoeff()<=0)throw std::runtime_error("independent full-rank contact rows required");
 auto response=s.force(q,0);Eigen::VectorXd f0=response.value,f1=s.force(q,.0001).value,f2=s.force(q,.0002).value,unit=(f1-f0)/.0001;double affine=(f2-f0-2*(f1-f0)).norm();if(affine>1e-15)throw std::runtime_error("frozen tendon-force affine check fails");
 Eigen::VectorXd direct=unit.cwiseQuotient(diag),normalControl=g.J*direct,projected=direct-miJ*factor.solve(normalControl),delayed=g.J*(response.negativeTangent*projected).cwiseQuotient(diag),second=factor.solve(delayed);double skinSquare=0,railSquare=0;for(unsigned f=0;f<3;++f){const auto&m=s.shared.films[f].film;for(unsigned a=0;a<m.index.size();++a)if(m.index[a]>=0){double x=unit(f*nf+m.index[a]);if(a/3<105)skinSquare+=x*x;else railSquare+=x*x;}}
 std::ofstream gain(std::string(argv[2])+".gain.csv");gain<<std::setprecision(17)<<"unit_force_norm,unit_skin_force_norm,unit_rail_force_norm,direct_normal_acceleration_gain_norm,linearized_reaction_second_time_derivative_gain_norm\n"<<unit.norm()<<','<<std::sqrt(skinSquare)<<','<<std::sqrt(railSquare)<<','<<normalControl.norm()<<','<<second.norm()<<'\n';
 std::ofstream out(argv[2]);out<<std::setprecision(17)<<"time,velocity_case,body_external_z_N,tension_per_rail_N,lambda0_N,lambda1_N,lambda2_N,all_signed_reactions_nonnegative,body_ax_mm_s2,body_ay_mm_s2,body_az_mm_s2,normal_acceleration_residual,force_affine_error_N,gap_max_mm,normal_velocity_max_mm_s\n";
 for(unsigned mode=0;mode<2;++mode)for(double load:{-.001,-.981})for(double T:{0.,.0001,.001,.01,.1}){
  Eigen::VectorXd vel=mode?v:Eigen::VectorXd::Zero(n),applied=f0+T*unit-2*s.shared.M*vel;applied(3*nf+2)+=load+.001;Eigen::VectorXd a=applied.cwiseQuotient(diag),free=g.J*a;for(unsigned i=0;i<3;++i)free(i)+=vel.dot(g.H[i]*vel);Eigen::VectorXd lambda=factor.solve(-free),normal=free+W*lambda;double bound=64*std::numeric_limits<double>::epsilon()*(free.norm()+W.norm()*lambda.norm());if(normal.norm()>bound)throw std::runtime_error("signed diagnostic backward error fails");Eigen::VectorXd acc=(applied+g.J.transpose()*lambda).cwiseQuotient(diag);
  out<<time<<','<<(mode?"actual_velocity":"zero_velocity_same_geometry")<<','<<load<<','<<T;for(double x:lambda)out<<','<<x;out<<','<<(lambda.minCoeff()>=0)<<','<<acc(3*nf)<<','<<acc(3*nf+1)<<','<<acc(3*nf+2)<<','<<normal.norm()<<','<<affine<<','<<g.gap.cwiseAbs().maxCoeff()<<','<<(g.J*v).cwiseAbs().maxCoeff()<<'\n';
 }
 std::cout<<"PASS independent frozen signed-reaction/control sensitivity;NOT dynamics/static equilibrium/holding capacity\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
